// Telegram Signal Parser
const message = $input.item.json.body.message || '';

// Clean message
let cleanMessage = message;
cleanMessage = cleanMessage.replace(/[🟢🔴⚡️📊💰🎯❌️]/g, '');
cleanMessage = cleanMessage.replace(/\(https?:\/\/[^\)]+\)/g, '');
cleanMessage = cleanMessage.replace(/\(buy\)|\(sell\)/gi, '');
cleanMessage = cleanMessage.toUpperCase().trim();

const result = {
  raw_message: message,
  parsed: false,
  coin: null,
  direction: null,
  leverage: null,
  margin_type: null,
  entry_min: null,
  entry_max: null,
  entry: null,
  targets: [],
  stoploss: null,
  symbol: null,
  error: null
};

try {
  // 1. Extract Coin and Direction
  const coinMatch = cleanMessage.match(/([A-Z0-9]+)\/USDT.*?(LONG|SHORT)/);
  if (coinMatch) {
    result.coin = coinMatch[1];
    result.direction = coinMatch[2];
    result.symbol = result.coin + 'USDT';
  }

  // 2. Extract Margin Type and Leverage
  const marginMatch = cleanMessage.match(/MARGIN:\s*(CROSS|ISOLATED),?\s*(\d+)X/);
  if (marginMatch) {
    result.margin_type = marginMatch[1];
    result.leverage = parseInt(marginMatch[2]);
  } else {
    // Fallback to just leverage
    const leverageMatch = cleanMessage.match(/MARGIN:.*?(\d+)X/);
    if (leverageMatch) {
      result.leverage = parseInt(leverageMatch[1]);
    }
  }

  // 3. Extract Entry Range
  const entryMatch = cleanMessage.match(/ENTRY:.*?<([0-9.]+)-([0-9.]+)>/);
  if (entryMatch) {
    result.entry_min = parseFloat(entryMatch[1]);
    result.entry_max = parseFloat(entryMatch[2]);
    result.entry = (result.entry_min + result.entry_max) / 2;
  }

  // 4. Extract Targets
  const targetMatches = cleanMessage.matchAll(/\d+\.\s*\[([0-9.]+)\]/g);
  for (const match of targetMatches) {
    result.targets.push(parseFloat(match[1]));
  }

  // 5. Extract Stop Loss
  const slMatch = cleanMessage.match(/STOPLOSS:.*?\[([0-9.]+)\]/);
  if (slMatch) {
    result.stoploss = parseFloat(slMatch[1]);
  }

  // Validation
  const isValid = 
    result.coin && 
    result.direction && 
    result.leverage && 
    result.entry && 
    result.stoploss && 
    result.targets.length > 0;

  if (isValid) {
    // Additional validation
    if (result.direction === 'LONG') {
      if (result.stoploss >= result.entry) {
        result.error = 'LONG: Stop loss must be below entry';
      } else if (result.targets.some(t => t <= result.entry)) {
        result.error = 'LONG: All targets must be above entry';
      } else {
        result.parsed = true;
      }
    } else if (result.direction === 'SHORT') {
      if (result.stoploss <= result.entry) {
        result.error = 'SHORT: Stop loss must be above entry';
      } else if (result.targets.some(t => t >= result.entry)) {
        result.error = 'SHORT: All targets must be below entry';
      } else {
        result.parsed = true;
      }
    }

    // Leverage validation
    if (result.leverage <= 0 || result.leverage > 125) {
      result.error = 'Invalid leverage: ' + result.leverage;
      result.parsed = false;
    }
  } else {
    result.error = 'Missing required fields';
  }

} catch (error) {
  result.error = error.message;
}

return { json: result };
